#!/bin/bash

# Set namespace based on the branch name
NAMESPACE=$(echo "${GITHUB_REF_NAME}" | tr '[:upper:]' '[:lower:]')
case $NAMESPACE in
  dev) NAMESPACE="dev" ;;
  stg) NAMESPACE="stg" ;;
  prod) NAMESPACE="prod" ;;
  sandbox) NAMESPACE="sandbox" ;;
  *) echo "Unsupported namespace: $NAMESPACE" && exit 1 ;;
esac

# Set AWS credentials based on the namespace
case $NAMESPACE in
  dev) ROLE_ARN=${GITHUB_SECRETS_DEV_GITHUB_MDL_CLOUD_SERVERLESS_ROLE} ;;
  stg) ROLE_ARN=${GITHUB_SECRETS_STG_GITHUB_MDL_CLOUD_SERVERLESS_ROLE} ;;
  prod) ROLE_ARN=${GITHUB_SECRETS_PROD_GITHUB_MDL_CLOUD_SERVERLESS_ROLE} ;;
  sandbox) ROLE_ARN=${GITHUB_SECRETS_SANDBOX_GITHUB_MDL_CLOUD_SERVERLESS_ROLE} ;;
  *) echo "Unsupported namespace: $NAMESPACE" && exit 1 ;;
esac

# Configure AWS credentials
aws configure set aws_access_key_id $AWS_ACCESS_KEY_ID
aws configure set aws_secret_access_key $AWS_SECRET_ACCESS_KEY
aws configure set aws_session_token $AWS_SESSION_TOKEN
aws configure set region $AWS_REGION
aws configure set role_arn $ROLE_ARN

# Upload latest changes to S3 bucket
bucket_list=$(aws s3 ls | awk '{print $3}')
for bucket in $bucket_list; do
  if [[ "$bucket" == *"${PROJECT_NAME}-${NAMESPACE}"* ]]; then
    if [[ "$bucket" != *"logs" ]]; then
      aws s3 sync static_website/ s3://$bucket --delete
    fi
  fi
done

# Create Cloudfront invalidation to pick name changes
distributions=$(aws cloudfront list-distributions | jq -r '.DistributionList.Items[] | .AliasICPRecordals[].CNAME')
case $NAMESPACE in
  dev) DISTRIBUTION_CNAME="${PROJECT_NAME}.dev.deployer.mckinsey.com" ;;
  stg) DISTRIBUTION_CNAME="${PROJECT_NAME}.stg.deployer.mckinsey.com" ;;
  prod) DISTRIBUTION_CNAME="${PROJECT_NAME}.deployer.mckinsey.com" ;;
  sandbox) DISTRIBUTION_CNAME="${PROJECT_NAME}.sandbox.deployer.mckinsey.com" ;;
  *) echo "Unsupported namespace: $NAMESPACE" && exit 1 ;;
esac

for item in $distributions; do
  if [[ "$item" == "$DISTRIBUTION_CNAME" ]]; then
    id=$(aws cloudfront list-distributions | jq -r '.DistributionList.Items[] | select(.AliasICPRecordals[].CNAME == "'$item'") | .Id')
    invalidation_id=$(aws cloudfront create-invalidation --distribution-id $id --paths "/*" | jq -r '.Invalidation.Id')
    aws cloudfront wait invalidation-completed --distribution-id $id --id $invalidation_id
  fi
done
