Here's an example of how you can use Python with the `requests` and `BeautifulSoup` libraries to recursively find all the direct URLs to the files at the specified URL.

```python
import requests
from bs4 import BeautifulSoup
import os

def get_file_urls(url):
    try:
        response = requests.get(url)
        soup = BeautifulSoup(response.text, 'html.parser')
        file_urls = []
        for link in soup.find_all('a'):
            href = link.get('href')
            if href and href.startswith('/'):
                file_url = url + href
                if os.path.splitext(href)[1]:
                    file_urls.append(file_url)
        return file_urls
    except Exception as e:
        print(f"Error occurred: {e}")
        return []

def recursive_get_file_urls(url, max_depth=5):
    file_urls = get_file_urls(url)
    if file_urls:
        print(f"Found {len(file_urls)} file URLs at {url}")
    for file_url in file_urls:
        if file_url.endswith(('.jpg', '.png', '.gif', '.bmp', '.pdf', '.txt', '.docx', '.xlsx', '.pptx')):
            print(f"Found file URL: {file_url}")
        else:
            recursive_get_file_urls(file_url, max_depth=max_depth - 1)

url = "https://arcjav.arcjavdb.workers.dev/0:/001-050/%E4%B8%8A%E5%8E%9F%E4%BA%9A%E8%A1%A3/"
