class Entity {
  constructor() {
    this.x = canvas.width;
    this.y = Math.random() * canvas.height;
    this.w = 20;
    this.h = 20;
    this.vx = -1 - Math.random() * 3;
    this.vy = 0;
    this.jumping = false;
    this.projectiles = [];
    this.color = "blue";
    this.targetX = 0; // new property to store the target x position
  }

  jump() {
    if (!this.jumping) {
      this.vy -= 10;
      this.jumping = true;
    }
  }

  update(platforms) {
    for (let i = 0; i < platforms.length; i++) {
      platforms[i].collidesWith(this);
    }

    const friction = 0.9;
    const gravity = 1;
    this.vx = friction * (this.vx + (this.targetX - this.x) * 0.1); // update x position towards target
    this.vy += gravity;
    this.x += this.vx;
    this.y += this.vy;

    if (Math.random() < 0.01) {
      this.projectiles.push(new Projectile(this.x, this.y, -2 - Math.random() * 6, -2 + Math.random() * 8));
    }

    for (let i = 0; i < this.projectiles.length; i++) {
      this.projectiles[i].update();
      if (this.projectiles[i].x < 0 || this.projectiles[i].y < 0 || this.projectiles[i].x > canvas.width || this.projectiles[i].y > canvas.height) {
        this.projectiles.splice(i, 1);
        i--;
      }
    }

    if (Math.random() < 0.01) {
      this.jump();
    }
  }

  draw(ctx) {
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x, this.y, this.w, this.h);
    for (let i = 0; i < this.projectiles.length; i++) {
      this.projectiles[i].draw(ctx);
    }
  }
}
