```

### 3. Create a MeshLoader class

Create a `MeshLoader` class that will handle loading 3D models using ASSIMP.

```cpp
// mesh_loader.h
#pragma once

#include <assimp/Importer.hpp>
#include <assimp/scene.h>
#include <assimp/postprocess.h>

class MeshLoader {
public:
    static std::shared_ptr<Mesh> LoadMesh(const std::string& filePath);
};
```

```cpp
// mesh_loader.cpp
#include "mesh_loader.h"
#include "mesh.h"

std::shared_ptr<Mesh> MeshLoader::LoadMesh(const std::string& filePath) {
    Assimp::Importer importer;
    const aiScene* scene = importer.ReadFile(filePath, aiProcess_Triangulate | aiProcess_FlipUVs);

    if (!scene || scene->mFlags & AI_SCENE_FLAGS_INCOMPLETE || !scene->mRootNode) {
        // Handle loading error
        return nullptr;
    }

    // Create a new mesh
    std::shared_ptr<Mesh> mesh = std::make_shared<Mesh>();

    // Load vertices and indices
    for (const aiMesh* mesh : scene->mMeshes) {
        // Load vertices
        for (const aiVertex& vertex : mesh->mVertices) {
            mesh->AddVertex(glm::vec3(vertex.x, vertex.y, vertex.z));
        }

        // Load indices
        for (const aiFace& face : mesh->mFaces) {
            for (const aiIndex& index : face.mIndices) {
                mesh->AddIndex(index);
            }
        }
    }

    return mesh;
}
```

